exercises.starterCode:
// Despliegue de una función de informes en una VPC. Corrige sus defectos.
export const despliegue = {
  funcion: "informes",
  subredes: [
    { id: "subred-a", tipo: "publica" },
    { id: "subred-b", tipo: "publica" },
  ],
  gruposSeguridad: ["sg-informes"],
  politicasRol: ["AWSLambdaBasicExecutionRole"],
  accesoInternet: { configurado: false },
  recursosPrivados: ["rds-reportes"],
};

solution.code:
export const despliegue = {
  funcion: "informes",
  subredes: [
    { id: "subred-a", tipo: "privada" },
    { id: "subred-b", tipo: "privada" },
  ],
  gruposSeguridad: ["sg-informes"],
  politicasRol: ["AWSLambdaBasicExecutionRole", "AWSLambdaVPCAccessExecutionRole"],
  accesoInternet: { configurado: true },
  recursosPrivados: ["rds-reportes"],
};

spec.code:
assert.ok(despliegue.subredes.length >= 1, "debe haber al menos una subred");
for (const s of despliegue.subredes) {
  assert.strictEqual(s.tipo, "privada", "la subred " + s.id + " debe ser privada");
}
